 * 4. Seller creates a product under that category.
 * 5. Seller creates a variant with initial stock for the product.
 * 6. Customer registers, adds the variant to cart, and places an order.
 * 7. Order items enter "paid" status, creating pending order constraints.
 * 8. Administrator deletes the variant via the admin endpoint, bypassing constraints.
 */
export async function test_api_variant_admin_delete_bypass_pending_orders(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
