export async function test_api_inventory_record_retrieve_restock(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - register and create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - register
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Create product under the category
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 4. Create variant with specific option values
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: {
          optionValues: [
            { key: "color", value: "Red" },
            { key: "size", value: "Large" },
          ],
        },
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // 5. Create inventory record (restock)
  const quantityChange = 50;
  const reason = "Quarterly restock";
  const createdRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        body: {
          quantity_change: quantityChange,
          reason,
        },
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(createdRecord);
  // 6. Retrieve the specific inventory record
  const retrievedRecord =
    await api.functional.shoppingMall.seller.products.variants.inventory_records.at(
      sellerConnection,
      {
        productId: product.id,
        variantId: variant.id,
        recordId: createdRecord.id,
      },
    );
  typia.assert(retrievedRecord);
  // 7. Validate the retrieved record
  TestValidator.equals("record id", retrievedRecord.id, createdRecord.id);
  TestValidator.equals(
    "quantity change",
    retrievedRecord.quantity_change,
    quantityChange,
  );
  TestValidator.equals("reason", retrievedRecord.reason, reason);
  TestValidator.predicate("created_at is recent", () => {
    const createdAt = new Date(retrievedRecord.created_at).getTime();
    const now = Date.now();
    return createdAt > 0 && createdAt <= now;
  });
  TestValidator.equals("variant id", retrievedRecord.variant.id, variant.id);
  TestValidator.equals(
    "variant code",
    retrievedRecord.variant.code,
    variant.code,
  );
  TestValidator.predicate(
    "variant has stock quantity",
    retrievedRecord.variant.stock_quantity >= 0,
  );
  TestValidator.predicate(
    "variant has option values",
    retrievedRecord.variant.optionValues.length > 0,
  );
  TestValidator.predicate(
    "variant has price field",
    retrievedRecord.variant.price !== undefined,
  );
}

