/**
 * Verify that a seller cannot access inventory records belonging to another seller's product.
 *
 * Validates the hierarchical ownership authorization boundary for inventory record retrieval. The endpoint must enforce that only the seller who owns the product — and therefore the variant and its inventory records — can view individual inventory ledger entries.
 *
 * 1. Administrator joins and creates a product category for Seller A to use.
 * 2. Seller A joins, creates a product with a variant, and records an inventory entry (restock of +30).
 * 3. Seller B joins as a completely different seller with no ownership relationship to Seller A's resources.
 * 4. Seller B attempts to retrieve Seller A's inventory record using the productId, variantId, and recordId from Seller A's resources.
 * 5. The endpoint returns 403 Forbidden, confirming that the ownership check correctly rejects cross-seller access to inventory ledger data.
 */
export async function test_api_inventory_record_retrieve_cross_seller_forbidden(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller A registers and creates resources
  const sellerAConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerAConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerAConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerAConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerAConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(inventoryRecord);
  // 3. Seller B registers (different seller, no ownership of Seller A's product)
  const sellerBConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerBConnection, {});
  // 4. Seller B attempts to access Seller A's inventory record → must be forbidden
  await TestValidator.error(
    "cross-seller inventory record access should be forbidden",
    async () => {
      await api.functional.shoppingMall.seller.products.variants.inventory_records.at(
        sellerBConnection,
        {
          productId: product.id,
          variantId: variant.id,
          recordId: inventoryRecord.id,
        },
      );
    },
  );
}

