  // 3. Retrieve snapshot history — product exists but has never been edited
  const snapshots =
    await api.functional.shoppingMall.seller.products.snapshots.index(
      sellerConnection,
      {
        productId: product.id,
        body: {},
      },
    );
  typia.assert(snapshots);
