/**
 * Test retrieval of a standalone variant snapshot after a variant-only edit.
 *
 * Validates that when a seller updates a product variant without modifying the parent product, an immutable snapshot is automatically created capturing the variant's complete pre-edit state including SKU code, option values, price override, and stock quantity. The snapshot is retrievable by the owning seller and the productSnapshot reference is null, confirming this is a standalone variant-level snapshot rather than one nested under a product-level edit.
 *
 * 1. Administrator registers and creates a product category.
 * 2. Seller registers, is approved by the administrator.
 * 3. Seller creates a product and a variant with a SKU code and option values.
 * 4. Seller updates the variant's SKU code and price, triggering automatic snapshot creation.
 * 5. Seller retrieves the snapshot and validates that productSnapshot is null, confirming standalone variant-only edit.
 */
export async function test_api_variant_snapshot_retrieve_standalone_after_variant_edit(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // Create category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller registration
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  // 3. Admin approves seller
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 4. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: { shopping_mall_category_id: category.id },
    },
  );
  // 5. Seller creates variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  // 6. Seller updates variant — triggers standalone snapshot creation
  const newCode = RandomGenerator.alphaNumeric(8);
  const updatedVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      sellerConnection,
      {
        productId: product.id,
        variantId: variant.id,
        body: {
          code: newCode,
          price: (variant.price ?? product.base_price) + 1000,
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(updatedVariant);
  // 7. Retrieve the variant snapshot
  const snapshot =
    await api.functional.shoppingMall.seller.products.variants.snapshots.at(
      sellerConnection,
      {
        productId: product.id,
        variantCode: updatedVariant.code,
        snapshotId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  typia.assert(snapshot);
  // Validate business logic: standalone variant snapshot has null productSnapshot
  TestValidator.equals(
    "productSnapshot is null for standalone variant-only edit",
    snapshot.productSnapshot,
    null,
  );
}

