    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  typia.assert(sellerJoinResult);
  // 3. Administrator approves the pending seller
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
      sellerId: sellerJoinResult.id,
    });
  typia.assert(approvedSeller);
  // 4. Seller authenticates via login with stored credentials
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IShoppingMallSeller.ILogin,
  });
  // 5. Seller creates a product under the category
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: { shopping_mall_category_id: category.id },
    },
  );
  typia.assert(product);
  // 6. Seller creates a variant with a globally unique SKU code
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 7. Seller updates the variant to trigger snapshot creation
  const updatedVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      sellerConnection,
      {
        productId: product.id,
        variantId: variant.id,
        body: {
          price: 1500,
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(updatedVariant);
  // 8. Seller soft-deletes the product
  await api.functional.shoppingMall.seller.products.erase(sellerConnection, {
    productId: product.id,
  });
  // 9. Retrieve the variant snapshot after product deletion
  const snapshot =
    await api.functional.shoppingMall.seller.products.variants.snapshots.at(
      sellerConnection,
      {
        productId: product.id,
        variantCode: variant.code,
        snapshotId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  typia.assert(snapshot);
}

