/**
 * Test that a customer cannot retrieve another customer's private wishlist item.
 *
 * Validates strict customer-scoped access control on the wishlist item retrieval endpoint. Each customer's wishlist is private — only the owner may view their wishlist items. Attempts by a different authenticated customer to access another customer's wishlist item must be rejected with 403 Forbidden.
 *
 * 1. Administrator registers, authenticates, and creates a product category.
 * 2. Seller registers with explicit credentials, is approved by the admin, re-authenticates to obtain an updated token, and creates a product in the category.
 * 3. Customer A registers, authenticates, and adds the product to their wishlist, creating a wishlist item.
 * 4. Customer B registers and authenticates as a different customer.
 * 5. Customer B attempts to retrieve Customer A's wishlist item — the system rejects with 403 Forbidden.
 */
export async function test_api_wishlist_item_retrieve_by_other_customer_forbidden(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerJoinConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerJoinConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
      sellerId: seller.id,
    });
  typia.assert(approvedSeller);
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  typia.assert(product);
  // 3. Customer A wishlist
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {});
  const wishlistItem =
    await generate_random_shopping_mall_customer_wishlist_items_create(
      customerAConnection,
      { body: { product_id: product.id } },
    );
  typia.assert(wishlistItem);
  // 4. Customer B unauthorized access
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {});
  await TestValidator.httpError(
    "Customer B cannot retrieve Customer A's wishlist item",
    403,
    async () => {
      await api.functional.shoppingMall.customer.wishlist_items.at(
        customerBConnection,
        { wishlistItemId: wishlistItem.id },
      );
    },
  );
}

