/**
 * Test cart item quantity update exceeding available stock.
 *
 * Validates that updating a cart item's quantity to exceed the variant's available stock still succeeds with HTTP 200, but the computed availability flag correctly reflects the stock shortfall.
 *
 * The update endpoint is designed to always succeed regardless of stock constraints — it returns computed availability warnings rather than blocking the quantity change. This allows the customer to see the warning and adjust their cart before proceeding to checkout.
 *
 * 1. Administrator creates a product category.
 * 2. Seller registers, creates a product under the category, generates a variant (SKU) with no initial stock, then records 5 units of stock via an inventory record.
 * 3. Customer registers and adds 1 unit of the variant to their cart.
 * 4. Customer updates the cart item quantity from 1 to 100 units.
 * 5. Validates the update returns HTTP 200 with the requested quantity of 100 applied and the available flag set to false because stock (5 units) is less than the requested quantity (100 units).
 */
export async function test_api_cart_item_quantity_update_exceeding_stock(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - create product, variant, and limited stock
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: {
          initialStockQuantity: 0,
        },
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // Record 5 units of stock
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      body: {
        quantity_change: 5,
        reason: "Initial stock",
      },
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  // 3. Customer setup - add item to cart with quantity 1
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          productVariantId: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 4. Update quantity to 100 (exceeds stock of 5)
  const updatedCartItem =
    await api.functional.shoppingMall.customer.cart_items.update(
      customerConnection,
      {
        cartItemId: cartItem.id,
        body: {
          quantity: 100,
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItem);
  // 5. Validate
  TestValidator.equals(
    "quantity updated to 100",
    updatedCartItem.quantity,
    100,
  );
  TestValidator.predicate(
    "available is false due to insufficient stock",
    !updatedCartItem.available,
  );
}

