/**
 * Test that a customer cannot access order items from another customer's order.
 *
 * Validates the customer-scoped access control on the order items listing endpoint. The endpoint must verify that the authenticated customer owns the specified order before returning any order items. When a different customer attempts to access the same order's items, the system must reject the request with an appropriate error response, preventing data leakage between customers.
 *
 * 1. Administrator registers and creates a product category.
 * 2. Seller registers, creates a product under the category, adds a variant with initial stock.
 * 3. Customer A registers and places an order with the variant.
 * 4. Customer B registers separately and attempts to access Customer A's order items.
 * 5. Verifies the system rejects Customer B's unauthorized access.
 */
export async function test_api_order_items_unauthorized_customer_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller creates product, variant, and stock
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { initialStockQuantity: 100 },
      },
    );
  typia.assert(variant);
  // 3. Customer A places an order
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {});
  const customerAOrder =
    await generate_random_shopping_mall_customer_orders_create(
      customerAConnection,
      {
        body: {
          items: [{ variant_id: variant.id, quantity: 1 }],
        },
      },
    );
  typia.assert(customerAOrder);
  // 4. Customer B attempts unauthorized access to Customer A's order items
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {});
  await TestValidator.error(
    "customer B cannot access customer A's order items",
    async () => {
      await api.functional.shoppingMall.customer.orders.items.index(
        customerBConnection,
        {
          orderId: customerAOrder.id,
          body: {},
        },
      );
    },
  );
}

