/**
 * Test that admin order item retrieval returns 404 for a non-existent item UUID.
 *
 * Validates that the admin order item detail endpoint correctly rejects requests
 * where the order code is valid but the item UUID does not correspond to any
 * existing order item. This confirms the cross-reference validation between the
 * order code and the item's parent order — administrators have platform-wide
 * access but the item must exist and belong to the specified order.
 *
 * 1. Administrator registers and creates a product category.
 * 2. Seller registers, creates a product under the category, a variant with
 *    a unique SKU code, and adds positive inventory stock.
 * 3. Customer registers and places an order for the variant to generate a
 *    valid order code.
 * 4. Administrator attempts to retrieve an order item using the valid order
 *    code paired with a randomly generated non-existent UUID, expecting a
 *    404 HttpError response.
 */
export async function test_api_order_item_admin_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 3. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 4. Create product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 5. Create variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 6. Add stock
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  // 7. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 8. Place order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // 9. Attempt to retrieve order item with non-existent UUID
  const fakeItemId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.httpError(
    "non-existent order item returns 404",
    404,
    async () => {
      await api.functional.shoppingMall.admin.orders.items.at(adminConnection, {
        orderCode: order.code,
        itemId: fakeItemId,
      });
    },
  );
}

