/**
 * Test customer shipment listing with full purchase-to-shipment workflow.
 *
 * Validates the customer's ability to list shipments for their own order after a seller dispatches a package. The test constructs the complete lifecycle: an administrator creates a product category, a seller registers and creates a product with a variant and inventory stock, a customer registers and places an order, and the seller creates a shipment containing the paid order item.
 *
 * The customer then calls the shipment listing endpoint and the test verifies that:
 *
 * 1. The response returns a paginated result with correct pagination metadata — current page, limit, total records, and total pages — reflecting exactly one shipment.
 * 2. Each shipment summary includes the carrier name, tracking number, shipping date (created_at), delivery status (derived as "pending" when delivered_at is null), seller information with shop profile, and the list of contained order items with their quantities, prices, and statuses.
 * 3. The order item transitions from "paid" to "shipped" status after the shipment is created, verified through the orderItems array within the shipment summary.
 * 4. The deliveryStatus field correctly maps null delivered_at to the string "pending".
 */
export async function test_api_shipment_list_customer_order_with_shipments(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller creates product, variant, and inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        quantity_change: 10,
        reason: "Initial stock for testing",
      },
    },
  );
  // 3. Customer places order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // 4. Seller creates shipment
  const orderItemId = order.items[0].id;
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          orderItemIds: [orderItemId],
          carrier_name: "TestCarrier",
          tracking_number: "TRACK-12345",
        },
      },
    );
  typia.assert(shipment);
  // 5. Customer lists shipments for the order
  const page =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      customerConnection,
      {
        orderId: order.id,
        body: {},
      },
    );
  typia.assert(page);
  // Validate pagination metadata
  TestValidator.equals("pagination current", page.pagination.current, 1);
  TestValidator.predicate(
    "pagination limit positive",
    page.pagination.limit > 0,
  );
  TestValidator.equals("pagination records", page.pagination.records, 1);
  TestValidator.equals("pagination pages", page.pagination.pages, 1);
  // Validate shipment data
  TestValidator.equals("data length", page.data.length, 1);
  const ship = page.data[0];
  TestValidator.equals("carrier name", ship.carrier_name, "TestCarrier");
  TestValidator.equals("tracking number", ship.tracking_number, "TRACK-12345");
  TestValidator.equals(
    "delivery status pending",
    ship.deliveryStatus,
    "pending",
  );
  TestValidator.equals("delivered at null", ship.delivered_at, null);
  TestValidator.predicate("order items non-empty", ship.orderItems.length >= 1);
  TestValidator.equals(
    "order item status shipped",
    ship.orderItems[0].status,
    "shipped",
  );
}

