/**
 * Test listing shipments for a newly placed order before any shipments are created.
 *
 * Validates that the shipments listing endpoint returns an empty paginated result
 * when an order has just been placed and no shipments have been created yet. This
 * is a valid intermediate state between order placement and seller shipment creation
 * — the endpoint must return an empty list rather than an error.
 *
 * 1. Administrator joins and creates a product category.
 * 2. Seller joins, creates a product with a variant, and adds inventory stock.
 * 3. Customer joins and places an order for the variant.
 * 4. Customer lists shipments for the order and validates an empty paginated result.
 */
export async function test_api_shipment_list_empty_for_new_order(
  connection: api.IConnection,
) {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: 100 satisfies number as number,
        reason: "Initial stock",
      },
    },
  );
  // 3. Customer setup and order placement
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  // 4. List shipments for the order (no shipments created yet)
  const result =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      customerConnection,
      {
        orderId: order.id,
        body: {},
      },
    );
  typia.assert(result);
  // 5. Validate empty paginated result
  TestValidator.equals("data should be an empty array", result.data.length, 0);
  TestValidator.equals(
    "pagination records should be zero",
    result.pagination.records,
    0,
  );
  TestValidator.equals(
    "pagination pages should be zero",
    result.pagination.pages,
    0,
  );
}

