/**
 * Test seller cancellation request filtering by pending status.
 *
 * Validates the critical seller workflow of identifying which cancellation
 * requests require review and action by filtering the cancellation request
 * listing to only "pending" status items.
 *
 * The test orchestrates a full multi-actor flow: a seller creates a product
 * with a purchasable variant, a customer purchases that variant and submits
 * a cancellation request, then the seller queries cancellation requests
 * filtered to "pending" status.
 *
 * 1. Seller registers and authenticates.
 * 2. Seller creates a product with a stocked variant.
 * 3. Customer registers and authenticates.
 * 4. Customer adds the variant to their cart and places an order.
 * 5. Customer submits a cancellation request for the paid order item.
 * 6. Seller queries cancellation requests with status="pending" filter.
 * 7. Verifies only pending requests are returned, pagination metadata
 *    reflects the filtered subset, and actor scoping is preserved.
 */
export async function test_api_cancellation_request_seller_filter_by_pending_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller registration and authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 2. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Seller creates a variant with initial stock
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: { initialStockQuantity: 10 },
      },
    );
  typia.assert(variant);
  // 4. Customer registration and authentication
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 5. Customer adds variant to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    {
      body: { productVariantId: variant.id, quantity: 1 },
    },
  );
  // 6. Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
        recipient_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        street_address: RandomGenerator.paragraph({ sentences: 3 }),
        city: "Seoul",
        state_province: "Seoul",
        postal_code: "06000",
        country: "South Korea",
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  typia.assert(orderItem);
  // 7. Customer submits a cancellation request for the paid order item
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        params: { itemId: orderItem.id },
      },
    );
  typia.assert(cancellationRequest);
  // 8. Seller queries cancellation requests filtered by "pending" status
  const filteredResult =
    await api.functional.shoppingMall.seller.cancellation_requests.index(
      sellerConnection,
      {
        body: {
          status: "pending",
        } satisfies IShoppingMallCancellationRequest.IRequest,
      },
    );
  typia.assert(filteredResult);
  // 9. Validate filtered results
  TestValidator.predicate(
    "at least one pending request returned",
    filteredResult.data.length >= 1,
  );
  TestValidator.predicate(
    "all returned requests are pending",
    filteredResult.data.every((r) => r.status === "pending"),
  );
  TestValidator.predicate(
    "submitted cancellation request appears in filtered results",
    filteredResult.data.some((r) => r.id === cancellationRequest.id),
  );
  TestValidator.equals(
    "specific request status is pending",
    cancellationRequest.status,
    "pending",
  );
  TestValidator.predicate(
    "pagination records reflects filtered subset",
    filteredResult.pagination.records >= filteredResult.data.length,
  );
  TestValidator.equals(
    "pagination current page is 1",
    filteredResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "results sorted by created_at descending (newest first)",
    (() => {
      for (let i = 1; i < filteredResult.data.length; i++) {
        if (
          filteredResult.data[i - 1].created_at <
          filteredResult.data[i].created_at
        ) {
          return false;
        }
      }
      return true;
    })(),
  );
}

