export async function test_api_cancellation_request_view_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 2. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 3. Add variant to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    {
      body: { productVariantId: variant.id, quantity: 1 },
    },
  );
  // 4. Place order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  // 5. Submit cancellation request
  const cancellationReason = "Changed my mind about this product";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        params: { itemId: orderItem.id },
        body: { reason: cancellationReason },
      },
    );
  typia.assert(cancellationRequest);
  // 6. Retrieve cancellation request by its UUID
  const retrievedRequest =
    await api.functional.shoppingMall.customer.cancellation_requests.at(
      customerConnection,
      { requestId: cancellationRequest.id },
    );
  typia.assert(retrievedRequest);
  // 7. Validate response fields
  TestValidator.equals(
    "reason matches input",
    retrievedRequest.reason,
    cancellationReason,
  );
  TestValidator.equals("status is pending", retrievedRequest.status, "pending");
  TestValidator.equals(
    "request id matches",
    retrievedRequest.id,
    cancellationRequest.id,
  );
  TestValidator.predicate(
    "order item exists",
    retrievedRequest.orderItem !== null,
  );
  TestValidator.equals(
    "order item id",
    retrievedRequest.orderItem.id,
    orderItem.id,
  );
  TestValidator.equals(
    "variant SKU code frozen",
    retrievedRequest.orderItem.productVariant.code,
    variant.code,
  );
  TestValidator.equals(
    "quantity frozen at purchase",
    retrievedRequest.orderItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "order item status is paid",
    retrievedRequest.orderItem.status,
    "paid",
  );
  TestValidator.equals(
    "snapshots are empty",
    retrievedRequest.snapshots.length,
    0,
  );
}

