/**
 * Test refund request submission after delivery confirmation.
 *
 * Validates that a customer can successfully submit a refund request for a delivered
 * order item within the 7-day eligibility window. The test covers the complete
 * lifecycle: admin approval of seller, product creation with inventory, order placement,
 * shipment creation, delivery confirmation, and finally the refund request submission.
 *
 * 1. Administrator creates a category and approves a seller.
 * 2. Seller creates a product with a variant and initial stock.
 * 3. Customer registers and places an order for the variant.
 * 4. Seller creates a shipment for the paid order items.
 * 5. Customer confirms delivery, transitioning items to "delivered".
 * 6. Customer submits a refund request with a valid reason.
 * 7. Validates the refund request has status "pending", reason is preserved,
 *    and responded_at remains null — confirming the request is awaiting seller review.
 */
export async function test_api_refund_request_submission_after_delivery(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller registration and approval
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 3. Seller creates product with variant and inventory
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        quantity_change: 100,
        reason: "Initial stock",
      },
    },
  );
  // 4. Customer registration
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 5. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // 6. Seller creates shipment
  const orderItem = order.items[0];
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          orderItemIds: [orderItem.id],
          carrier_name: "TestCarrier",
          tracking_number: "TRACK123",
        },
      },
    );
  typia.assert(shipment);
  // 7. Customer confirms delivery
  const deliveredShipment =
    await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(deliveredShipment);
  // 8. Customer submits refund request
  const refundReason = "Product does not match description";
  const refundRequest =
    await api.functional.shoppingMall.customer.order_items.refund_requests.create(
      customerConnection,
      {
        itemId: orderItem.id,
        body: {
          reason: refundReason,
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  // 9. Validate refund request business logic
  TestValidator.equals("refund status", refundRequest.status, "pending");
  TestValidator.equals(
    "refund reason preserved",
    refundRequest.reason,
    refundReason,
  );
  TestValidator.equals(
    "responded_at is null",
    refundRequest.responded_at,
    null,
  );
}

