export async function test_api_product_snapshot_access_denied_for_other_customer(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller registration and approval
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: sellerAuth.id,
  });
  // 3. Create product under approved seller
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  typia.assert(product);
  // 4. Create variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  // 5. Add positive inventory so variant is purchasable
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: { quantity_change: 100, reason: "Initial stock" },
    },
  );
  // 6. Upload product image for gallery snapshot
  await generate_random_shopping_mall_seller_products_images_create(
    sellerConnection,
    { params: { productId: product.id } },
  );
  // 7. First customer - places order and owns the snapshot
  const customer1Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer1Connection, {});
  // Add variant to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customer1Connection,
    { body: { productVariantId: variant.id, quantity: 1 } },
  );
  // Place order - creates product snapshots at purchase time
  const order = await generate_random_shopping_mall_customer_orders_create(
    customer1Connection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  // 8. Second customer - attempts unauthorized snapshot access
  const customer2Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer2Connection, {});
  // Second customer tries to access first customer's product snapshot
  await TestValidator.error(
    "cross-customer product snapshot access denied",
    async () => {
      await api.functional.shoppingMall.customer.order_items.product_snapshot.at(
        customer2Connection,
        { itemId: order.items[0].id },
      );
    },
  );
}

