export async function test_api_product_snapshot_retrieval_by_admin_with_full_data(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Seller registration
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  // 3. Admin approves seller
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
      sellerId: seller.id,
    });
  typia.assert(approvedSeller);
  // 4. Admin creates category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 5. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  // 6. Seller creates variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  // 7. Seller adds inventory stock
  const stockQuantity = 100 satisfies number as number;
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: stockQuantity,
        reason: "Initial stock for testing",
      },
    },
  );
  // 8. Customer registration
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 9. Customer adds to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    { body: { productVariantId: variant.id, quantity: 1 } },
  );
  // 10. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  // 11. Admin retrieves product snapshot
  const orderItemId = order.items[0].id;
  const snapshot =
    await api.functional.shoppingMall.admin.order_items.product_snapshot.at(
      adminConnection,
      { itemId: orderItemId },
    );
  typia.assert(snapshot);
  // 12. Validate frozen product data matches original values
  TestValidator.equals(
    "snapshot product name matches original",
    snapshot.name,
    product.name,
  );
  TestValidator.equals(
    "snapshot description matches original",
    snapshot.description,
    product.description,
  );
  TestValidator.equals(
    "snapshot base_price matches original",
    snapshot.base_price,
    product.base_price,
  );
  TestValidator.equals(
    "snapshot category_name matches original",
    snapshot.category_name,
    category.name,
  );
  TestValidator.equals(
    "snapshot shopping_mall_product_id references original product",
    snapshot.shopping_mall_product_id,
    product.id,
  );
  TestValidator.equals(
    "snapshot shopping_mall_category_id references original category",
    snapshot.shopping_mall_category_id,
    category.id,
  );
  // 13. Validate productSnapshotImages ordering
  const images = snapshot.productSnapshotImages;
  for (let i = 1; i < images.length; i++) {
    TestValidator.predicate(
      `image displayOrder ascending at index ${i}`,
      () => images[i].displayOrder >= images[i - 1].displayOrder,
    );
  }
}

