  const orderItem = order.items[0];
  // 9. Administrator retrieves the variant snapshot for the order item
  const snapshot =
    await api.functional.shoppingMall.admin.order_items.variant_snapshot.at(
      adminConnection,
      {
        itemId: orderItem.id,
      },
