/**
 * Test that seller snapshot correctly preserves null logo_image_url when the seller
 * had not uploaded a logo image at the time of order placement.
 *
 * Validates the nullable field semantics defined in IShoppingMallOrderItemSellerSnapshot
 * — a missing logo does not prevent snapshot creation or retrieval, and the null value
 * accurately reflects the seller's profile state at the moment of checkout.
 *
 * 1. Administrator registers and authenticates.
 * 2. Seller registers (without logo — logo_image_uri defaults to null) and authenticates.
 * 3. Administrator approves the seller so they can list products.
 * 4. Seller creates a product, adds a variant with SKU, and restocks inventory.
 * 5. Customer registers, adds the variant to the cart, and places an order.
 * 6. The seller snapshot is retrieved for the order item and validated.
 * 7. Confirms logo_image_url is null and all required fields are present.
 */
export async function test_api_seller_snapshot_null_logo_handling(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin registers and authenticates
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {});
  // 2. Seller registers (logo_image_uri defaults to null in seller profile)
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  // 3. Admin approves the seller
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 4. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  // 5. Seller creates a variant for the product
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  // 6. Seller adds inventory stock for the variant
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: 100 satisfies number as number,
        reason: "Initial stock for testing",
      },
    },
  );
  // 7. Customer registers and authenticates
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 8. Customer adds the variant to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    { body: { productVariantId: variant.id, quantity: 1 } },
  );
  // 9. Customer places the order with the variant
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  // 10. Retrieve the seller snapshot for the order item
  const orderItem = order.items[0];
  const snapshot =
    await api.functional.shoppingMall.customer.order_items.seller_snapshot.at(
      customerConnection,
      { itemId: orderItem.id },
    );
  typia.assert(snapshot);
  // 11. Validate the snapshot
  TestValidator.equals(
    "logo_image_url is null when seller had no logo at purchase time",
    snapshot.logo_image_url,
    null,
  );
  TestValidator.predicate(
    "snapshot shop_name is a non-empty string",
    snapshot.shop_name.length > 0,
  );
}

