/**
 * Test listing product snapshot images for an order item after purchase.
 *
 * Validates that when a customer places an order for a product with gallery images, the product snapshot created at order time captures all images with their correct URLs and display order positions as they existed at purchase time.
 *
 * The test also verifies that the pagination metadata (records, pages, current) correctly reflects the total number of images captured in the snapshot, and that each snapshot image record contains all required fields — id (UUID), image_url (URL), display_order (integer), and created_at (ISO 8601 datetime).
 *
 * 1. Seller registers and creates a product with a category and base price.
 * 2. Seller uploads two images to the product gallery with sequential display orders.
 * 3. Seller creates a purchasable variant and adds inventory stock.
 * 4. Customer registers, adds the variant to their cart, and places the order.
 * 5. Customer lists the product snapshot images for the resulting order item.
 * 6. Validates pagination metadata matches the image count (2 records, 1 page).
 * 7. Validates each snapshot image URL and display order matches the original product images at purchase time.
 */
export async function test_api_order_item_product_snapshot_images_list_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 2. Create product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {},
  );
  // 3. Upload two product images
  const image1 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  const image2 =
    await generate_random_shopping_mall_seller_products_images_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  const originalImages = [image1, image2].sort(
    (a, b) => a.display_order - b.display_order,
  );
  // 4. Create variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  // 5. Add inventory stock
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    { params: { productId: product.id, variantId: variant.id } },
  );
  // 6. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 7. Add variant to cart
  await generate_random_shopping_mall_customer_cart_items_create(
    customerConnection,
    { body: { productVariantId: variant.id, quantity: 1 } },
  );
  // 8. Place order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  // 9. Get the order item
  const orderItem = order.items[0];
  typia.assert(orderItem);
  // 10. List snapshot images
  const snapshotImages =
    await api.functional.shoppingMall.customer.order_items.product_snapshot.images.index(
      customerConnection,
      {
        itemId: orderItem.id,
        body: {},
      },
    );
  typia.assert(snapshotImages);
  // 11. Validate pagination metadata
  TestValidator.equals(
    "records matches image count",
    snapshotImages.pagination.records,
    originalImages.length,
  );
  TestValidator.equals("pages count", snapshotImages.pagination.pages, 1);
  TestValidator.equals("current page", snapshotImages.pagination.current, 1);
  // 12. Sort snapshot data by display_order for comparison
  const snapshotData = [...snapshotImages.data].sort(
    (a, b) => a.display_order - b.display_order,
  );
  // 13. Validate each snapshot image
  for (let i = 0; i < originalImages.length; i++) {
    const original = originalImages[i];
    const snapshot = snapshotData[i];
    TestValidator.equals(
      `image ${i} URL`,
      snapshot.image_url,
      original.image_url,
    );
    TestValidator.equals(
      `image ${i} display_order`,
      snapshot.display_order,
      original.display_order,
    );
  }
}

