/**
 * Test that seller rejection of a cancellation request creates an immutable snapshot.
 *
 * Validates the complete cancellation workflow ending in seller rejection, confirming
 * that the system automatically creates a snapshot preserving the customer's reason
 * text and the "rejected" status at the moment of the seller's decision.
 *
 * The test exercises the full order lifecycle: administrative category setup, seller
 * approval and product/variant/inventory creation, customer order placement, cancellation
 * request submission, seller rejection, and finally snapshot list retrieval.
 *
 * 1. Administrator joins and creates a category for product classification.
 * 2. Seller joins and is approved by the administrator.
 * 3. Seller creates a product, a variant with positive stock.
 * 4. Customer joins and places an order — order item enters "paid" status.
 * 5. Customer submits a cancellation request with a known reason text.
 * 6. Seller rejects the cancellation request — snapshot is created automatically.
 * 7. Seller retrieves the paginated snapshot list and validates the audit record.
 *    7.1. Exactly one snapshot exists in the list.
 *    7.2. The snapshot's reason matches the original cancellation reason.
 *    7.3. The snapshot's status is "rejected".
 *    7.4. Pagination metadata: 1 current page, 1 total record, 1 total page.
 */
export async function test_api_cancellation_snapshot_list_after_seller_rejection(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller registration and approval
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 3. Seller creates product, variant, and inventory
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: {
          optionValues: [
            { key: "color", value: "Red" },
          ] satisfies IShoppingMallProductVariantOptionValue.ICreate[],
        },
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      body: {
        quantity_change: 100,
        reason: "Initial stock for testing",
      },
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  // 4. Customer registration and order placement
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  typia.assert(orderItem);
  // 5. Customer submits cancellation request
  const cancellationReason = "Changed my mind about the purchase";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        body: { reason: cancellationReason },
        params: { itemId: orderItem.id },
      },
    );
  typia.assert(cancellationRequest);
  // 6. Seller rejects the cancellation request (creates snapshot)
  await api.functional.shoppingMall.seller.cancellation_requests.update(
    sellerConnection,
    {
      requestId: cancellationRequest.id,
      body: {
        status: "rejected",
      } satisfies IShoppingMallCancellationRequest.IUpdate,
    },
  );
  // 7. Seller retrieves paginated snapshot list
  const snapshotPage =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {} satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotPage);
  // 7.1. Validate exactly one snapshot
  TestValidator.equals("snapshot count", snapshotPage.data.length, 1);
  const snapshot = snapshotPage.data[0];
  // 7.2. Reason text preserved
  TestValidator.equals(
    "snapshot reason matches original",
    snapshot.reason,
    cancellationReason,
  );
  // 7.3. Status is rejected
  TestValidator.equals(
    "snapshot status is rejected",
    snapshot.status,
    "rejected",
  );
  // 7.4. Pagination metadata
  TestValidator.equals(
    "pagination current page",
    snapshotPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination total records",
    snapshotPage.pagination.records,
    1,
  );
  TestValidator.equals(
    "pagination total pages",
    snapshotPage.pagination.pages,
    1,
  );
}

