/**
 * Test that querying cancellation request snapshots before seller response returns an empty paginated result.
 *
 * Validates the edge case where a cancellation request exists in "pending" status but the seller has not yet responded. Since snapshots are only created when the seller approves or rejects the cancellation request, querying the snapshot list before any seller response should return an empty paginated result with zero records and zero pages.
 *
 * This confirms that the endpoint handles the absence of snapshots gracefully per the specification — returning a successful 200 response with an empty data array rather than an error or 404.
 *
 * 1. Administrator registers, creates a product category, and approves a new seller.
 * 2. Seller registers, creates a product with a purchasable variant, and adds inventory stock.
 * 3. Customer registers and places an order for the variant.
 * 4. Customer submits a cancellation request for the order item, which enters "pending" status.
 * 5. Seller queries the cancellation request's snapshot list before making any response.
 * 6. Validates the response is successful, the data array is empty, and pagination reflects zero records and zero pages.
 */
export async function test_api_cancellation_snapshot_list_empty_pending_request(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 3. Seller creates product, variant, and adds stock
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: { shopping_mall_category_id: category.id },
    },
  );
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 4. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 5. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  // 6. Customer submits cancellation request (enters "pending" status)
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        params: { itemId: order.items[0].id },
      },
    );
  // 7. Seller queries snapshots before responding to the cancellation request
  const result =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {},
      },
    );
  typia.assert(result);
  // 8. Validate empty snapshot list
  TestValidator.equals(
    "snapshot data array should be empty",
    result.data.length,
    0,
  );
  TestValidator.equals(
    "pagination records should be 0",
    result.pagination.records,
    0,
  );
  TestValidator.equals(
    "pagination pages should be 0",
    result.pagination.pages,
    0,
  );
}

