export async function test_api_cancellation_request_snapshot_view_after_seller_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator registers and creates a product category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller registers
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  // 3. Administrator approves the seller
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 4. Seller creates a product with a variant and adds inventory
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: { shopping_mall_category_id: category.id },
    },
  );
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 5. Customer registers and places an order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [{ variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  // 6. Customer submits a cancellation request with a descriptive reason
  const reasonText =
    "Item no longer needed - changed my mind after reviewing order details";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        body: { reason: reasonText },
        params: { itemId: order.items[0].id },
      },
    );
  // 7. Seller approves the cancellation request, which creates an immutable snapshot
  const updatedRequest =
    await api.functional.shoppingMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(updatedRequest);
  const snapshotEntry = updatedRequest.snapshots[0]!;
  typia.assertGuard(snapshotEntry);
  // 8. Customer retrieves the cancellation request snapshot
  const snapshot =
    await api.functional.shoppingMall.customer.cancellation_requests.snapshots.at(
      customerConnection,
      {
        requestId: cancellationRequest.id,
        snapshotId: snapshotEntry.id,
      },
    );
  typia.assert(snapshot);
  // 9. Validate snapshot properties
  TestValidator.equals(
    "reason matches original submission",
    snapshot.reason,
    reasonText,
  );
  TestValidator.equals("status records approved", snapshot.status, "approved");
  TestValidator.predicate(
    "created_at reflects seller response time",
    new Date(snapshot.created_at).getTime() >
      new Date(cancellationRequest.created_at).getTime(),
  );
  TestValidator.equals(
    "cancellationRequest references correct parent",
    snapshot.cancellationRequest.id,
    cancellationRequest.id,
  );
}

