export async function test_api_cancellation_snapshot_access_denied_for_non_owning_seller(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller A setup
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerA = await authorize_seller_join(sellerAConnection, {});
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: sellerA.id,
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerAConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerAConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerAConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 3. Customer setup and order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          } as IShoppingMallOrderItem.ICreate,
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  // 4. Customer submits cancellation request
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      {
        params: { itemId: orderItem.id },
      },
    );
  typia.assert(cancellationRequest);
  // 5. Seller A approves cancellation request (creates snapshot)
  const approvedRequest =
    await api.functional.shoppingMall.seller.cancellation_requests.update(
      sellerAConnection,
      {
        requestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedRequest);
  const snapshot = approvedRequest.snapshots[0];
  typia.assert(snapshot);
  // 6. Seller B attempts to access the snapshot → should get 403
  const sellerBConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerBConnection, {});
  await TestValidator.httpError(
    "Seller B denied access to Seller A's cancellation snapshot",
    403,
    async () => {
      await api.functional.shoppingMall.seller.cancellation_requests.snapshots.at(
        sellerBConnection,
        {
          requestId: cancellationRequest.id,
          snapshotId: snapshot.id,
        },
      );
    },
  );
  // 7. Seller A re-accesses the snapshot → should get 200
  const reAccessedSnapshot =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.at(
      sellerAConnection,
      {
        requestId: cancellationRequest.id,
        snapshotId: snapshot.id,
      },
    );
  typia.assert(reAccessedSnapshot);
}

