/**
 * Test seller retrieval of an immutable refund request snapshot created on rejection.
 *
 * Validates the complete refund request lifecycle ending with the seller rejecting the request,
 * which triggers automatic snapshot creation. The seller then retrieves the snapshot via the
 * GET endpoint and verifies every snapshot field is correctly and immutably preserved.
 *
 * The test confirms that rejection outcomes are captured identically to approval outcomes
 * in the snapshot record, ensuring a complete audit trail regardless of the seller's decision.
 * Special attention is given to verifying that the reason text matches the customer's original
 * submission word-for-word, the status is 'rejected' (not 'approved'), the seller reference
 * correctly identifies the rejecting seller, and the created_at timestamp captures the exact
 * moment of the seller's response.
 *
 * 1. Administrator creates a product category.
 * 2. Seller registers and creates a product, variant, and initial inventory.
 * 3. Customer registers and places an order for the variant.
 * 4. Seller creates a shipment and customer confirms delivery.
 * 5. Customer submits a refund request with a detailed reason.
 * 6. Seller rejects the refund request, triggering snapshot creation.
 * 7. Seller retrieves the snapshot and validates all preserved fields.
 */
export async function test_api_refund_request_snapshot_seller_view_rejected(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup — authenticate and create product category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: {} },
  );
  typia.assert(category);
  // 2. Seller setup — register, create product, variant, and inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  typia.assert(seller);
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { shopping_mall_category_id: category.id } },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id }, body: {} },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: { quantity_change: 10 },
    },
  );
  // 3. Customer setup — register and place order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          } satisfies IShoppingMallOrderItem.ICreate,
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  typia.assert(orderItem);
  // 4. Shipment — seller ships the order item
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: { orderItemIds: [orderItem.id] },
      },
    );
  typia.assert(shipment);
  // 5. Delivery confirmation — customer confirms receipt
  await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
    customerConnection,
    { shipmentId: shipment.id },
  );
  // 6. Refund request — customer submits refund for delivered item
  const refundRequest =
    await generate_random_shopping_mall_customer_order_items_refund_requests_create(
      customerConnection,
      { params: { itemId: orderItem.id } },
    );
  typia.assert(refundRequest);
  // 7. Seller rejects the refund request — triggers snapshot creation
  const updatedRefundRequest =
    await api.functional.shoppingMall.seller.refund_requests.update(
      sellerConnection,
      {
        requestId: refundRequest.id,
        body: {
          status: "rejected",
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // 8. Retrieve the auto-created snapshot
  const snapshotId = (
    updatedRefundRequest as unknown as {
      snapshots?: Array<{
        id: string;
      }>;
    }
  ).snapshots?.[0]?.id;
  if (snapshotId === undefined)
    throw new Error("Snapshot was not created on rejection");
  const snapshot =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.at(
      sellerConnection,
      { requestId: refundRequest.id, snapshotId },
    );
  typia.assert(snapshot);
  // 9. Validate snapshot fields
  TestValidator.equals(
    "reason matches customer's original submission word-for-word",
    snapshot.reason,
    refundRequest.reason,
  );
  TestValidator.equals(
    "status is rejected (not approved)",
    snapshot.status,
    "rejected",
  );
  TestValidator.equals(
    "seller reference identifies the rejecting seller",
    snapshot.seller.id,
    seller.id,
  );
  TestValidator.equals(
    "created_at captures the exact moment of rejection",
    snapshot.created_at,
    updatedRefundRequest.responded_at!,
  );
  TestValidator.equals(
    "refund request reference matches parent",
    snapshot.refundRequest.id,
    refundRequest.id,
  );
}

