/**
 * Test that an unauthorized customer cannot access cancellation request snapshots.
 *
 * Validates the cross-actor authorization boundary for cancellation request snapshot access. After a seller responds to a cancellation request and the system creates an immutable snapshot, a different customer who did not place the order and did not submit the cancellation request attempts to list the snapshots. The system must reject the request with a 403 Forbidden response because the accessing customer is neither the owner of the cancellation request, the seller of the product, nor an administrator.
 *
 * 1. Administrator creates a product category for the seller's product.
 * 2. Seller registers, creates a product under the category, adds a variant with a unique SKU code, and stocks inventory.
 * 3. Customer 1 (the order owner) registers and places an order for the variant with quantity 1.
 * 4. Customer 1 submits a cancellation request for the paid order item with a reason.
 * 5. Seller approves the cancellation request — the system automatically creates an immutable snapshot recording the approval decision.
 * 6. Customer 2 (a different, unrelated customer) registers.
 * 7. Customer 2 attempts to access the cancellation request snapshots and receives 403 Forbidden.
 */
export async function test_api_cancellation_request_snapshot_unauthorized_customer_forbidden(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates a product category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller registers, creates product, variant, and stocks inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: { shopping_mall_category_id: category.id },
    },
  );
  typia.assert(product);
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 3. Customer 1 (order owner) registers and places an order
  const customer1Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer1Connection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customer1Connection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  // 4. Customer 1 submits a cancellation request
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customer1Connection,
      {
        params: { itemId: orderItem.id },
      },
    );
  typia.assert(cancellationRequest);
  // 5. Seller approves the cancellation request (snapshot created automatically)
  const updatedRequest =
    await api.functional.shoppingMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(updatedRequest);
  // 6. Customer 2 (unauthorized, different customer) registers
  const customer2Connection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customer2Connection, {});
  // 7. Customer 2 attempts to access snapshots — must receive 403 Forbidden
  await TestValidator.error(
    "unauthorized customer cannot access cancellation request snapshots",
    async () => {
      await api.functional.shoppingMall.cancellation_requests.snapshots.index(
        customer2Connection,
        {
          requestId: cancellationRequest.id,
          body: {} satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
        },
      );
    },
  );
}

