/**
 * Test adding multiple images to a product snapshot with distinct display orders.
 *
 * Validates that the frozen product snapshot gallery can hold multiple images with
 * independently identifiable UUIDs and distinct display order positions. The snapshot
 * is captured at order placement time and images added to it form an immutable
 * historical record of the product gallery as presented at purchase time.
 *
 * The test verifies that two images added to the same snapshot each receive unique
 * server-generated IDs and are positioned correctly within the gallery: the first at
 * display_order 0 (thumbnail) and the second at display_order 1 (next in sequence).
 * Both images share the same product snapshot parent reference.
 *
 * 1. Administrator creates a category for product classification.
 * 2. Seller registers, gets approved by admin, creates a product, variant, and stock.
 * 3. Customer registers and places an order for the variant.
 * 4. First snapshot image added with display_order 0.
 * 5. Second snapshot image added with display_order 1.
 * 6. Validates unique IDs, correct display orders, and shared snapshot reference.
 */
export async function test_api_product_snapshot_image_add_multiple_positions(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller registration and approval
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 3. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 4. Seller creates variant with stock
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        quantity_change: 10,
        reason: "Initial stock",
      },
    },
  );
  // 5. Customer places order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  typia.assert(orderItem);
  // 6. Add first snapshot image at display_order 0 (thumbnail)
  const firstImage =
    await generate_random_shopping_mall_order_items_product_snapshot_images_create(
      connection,
      {
        params: { itemId: orderItem.id },
        body: { display_order: 0 },
      },
    );
  typia.assert(firstImage);
  // 7. Add second snapshot image at display_order 1
  const secondImage =
    await generate_random_shopping_mall_order_items_product_snapshot_images_create(
      connection,
      {
        params: { itemId: orderItem.id },
        body: { display_order: 1 },
      },
    );
  typia.assert(secondImage);
  // 8. Validate
  TestValidator.notEquals("IDs are distinct", firstImage.id, secondImage.id);
  TestValidator.equals(
    "first image at thumbnail position",
    firstImage.displayOrder,
    0,
  );
  TestValidator.equals(
    "second image follows thumbnail",
    secondImage.displayOrder,
    1,
  );
  TestValidator.equals(
    "both images belong to same snapshot",
    firstImage.productSnapshot.id,
    secondImage.productSnapshot.id,
  );
}

