export async function test_api_review_create_with_full_content(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  // 2. Seller registration and approval
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {});
  await api.functional.shoppingMall.admin.sellers.approve(adminConnection, {
    sellerId: seller.id,
  });
  // 3. Seller creates product with variant and inventory
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        quantity_change: 100,
        reason: "Initial restock for E2E test",
      },
    },
  );
  // 4. Customer registration
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  // 5. Customer places order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // 6. Seller creates shipment
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: {
          orderId: order.id,
        },
        body: {
          orderItemIds: order.items.map((item) => item.id),
        },
      },
    );
  // 7. Customer confirms delivery
  await api.functional.shoppingMall.customer.shipments.confirm_delivery.confirmDelivery(
    customerConnection,
    {
      shipmentId: shipment.id,
    },
  );
  // 8. Customer creates review
  const reviewContent = RandomGenerator.paragraph({ sentences: 3 });
  const review = await generate_random_shopping_mall_customer_reviews_create(
    customerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
        shopping_mall_order_id: order.id,
        shopping_mall_order_item_id: order.items[0].id,
        rating: 5,
        content: reviewContent,
      },
    },
  );
  typia.assert(review);
  // 9. Validate review
  TestValidator.equals("rating is 5", review.rating, 5);
  TestValidator.equals("content matches input", review.content, reviewContent);
  TestValidator.equals(
    "customer display_name matches",
    review.customer.display_name,
    customer.display_name,
  );
  TestValidator.equals(
    "snapshots array is empty on creation",
    review.snapshots.length,
    0,
  );
  TestValidator.equals("deleted_at is null", review.deleted_at, null);
  TestValidator.predicate("product summary exists", review.product !== null);
  TestValidator.predicate("order summary exists", review.order !== null);
  TestValidator.predicate(
    "orderItem summary exists",
    review.orderItem !== null,
  );
  TestValidator.predicate("review id is set", review.id !== "");
  TestValidator.predicate("created_at is set", review.created_at !== "");
  TestValidator.predicate("updated_at is set", review.updated_at !== "");
}

