/**
 * Test administrator force-cancellation of an order containing already-cancelled items.
 *
 * Validates that when an administrator force-cancels an order where some items have already been cancelled through the normal seller-approval workflow, the system correctly skips the already-cancelled items and processes only the remaining ones, resulting in all items being cancelled and the order status deriving as "cancelled".
 *
 * The test verifies the partial processing behavior: already-cancelled items should not trigger duplicate cancellation requests, snapshots, refunds, or inventory records, while items still in "paid" status are force-cancelled normally.
 *
 * 1. Administrator authenticates and creates a product category.
 * 2. Seller registers, creates a product with two variants, and adds stock.
 * 3. Customer registers and places an order with both variants.
 * 4. Customer submits a cancellation request for one order item.
 * 5. Seller approves the cancellation request, making one item "cancelled".
 * 6. Administrator force-cancels the entire order with an administrative reason.
 * 7. Validates all items are in "cancelled" status and the order status is "cancelled".
 */
export async function test_api_admin_force_cancel_order_with_already_cancelled_items(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 3. Create two variants with stock
  const variant1 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant1);
  const variant2 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant2);
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    { params: { productId: product.id, variantId: variant1.id } },
  );
  await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
    sellerConnection,
    { params: { productId: product.id, variantId: variant2.id } },
  );
  // 4. Customer setup and order placement
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            variant_id: variant1.id,
            quantity: 1,
          } satisfies IShoppingMallOrderItem.ICreate,
          {
            variant_id: variant2.id,
            quantity: 1,
          } satisfies IShoppingMallOrderItem.ICreate,
        ],
      },
    },
  );
  typia.assert(order);
  const itemToCancel = order.items[0];
  // 5. Customer submits cancellation request for itemToCancel
  const cancellationRequest =
    await generate_random_shopping_mall_customer_order_items_cancellation_requests_create(
      customerConnection,
      { params: { itemId: itemToCancel.id } },
    );
  typia.assert(cancellationRequest);
  // 6. Seller approves the cancellation request
  const approvedCancellation =
    await api.functional.shoppingMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        requestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedCancellation);
  // 7. Administrator force-cancels the entire order
  const result =
    await api.functional.shoppingMall.admin.orders.force_cancel.forceCancel(
      adminConnection,
      {
        orderId: order.id,
        body: {
          reason: "Administrative force cancellation for testing",
        } satisfies IShoppingMallOrder.IForceCancel,
      },
    );
  typia.assert(result);
  // 8. Validate results
  TestValidator.predicate("order has items", result.items.length > 0);
  TestValidator.predicate(
    "all items are cancelled",
    result.items.every((item) => item.status === "cancelled"),
  );
  TestValidator.equals("order status is cancelled", result.status, "cancelled");
}

