  const orderItem = order.items[0];
  TestValidator.equals(
    "order item initial status is paid",
    orderItem.status,
    "paid",
  );
  // 9. Administrator force-refunds the order item
  const refundedItem =
    await api.functional.shoppingMall.admin.order_items.force_refund.forceRefund(
      adminConnection,
      { itemId: orderItem.id },
    );
  typia.assert(refundedItem);
  // 10. Validate force-refund results
  TestValidator.equals(
    "order item status changed to refunded",
    refundedItem.status,
    "refunded",
  );
  TestValidator.equals(
    "order item id preserved",
    refundedItem.id,
    orderItem.id,
  );
  TestValidator.equals(
    "order item quantity preserved",
    refundedItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "order item price preserved",
    refundedItem.price,
    orderItem.price,
  );
  TestValidator.notEquals(
    "updated_at changed after refund",
    refundedItem.updated_at,
    orderItem.updated_at,
  );
}

