/**
 * Test that querying review statistics for a non-existent product returns 404.
 *
 * Validates that the review statistics endpoint properly checks product existence before computing aggregate statistics. A customer is authenticated, then a randomly generated UUID — guaranteed to have no matching product in the database — is passed as the productId.
 *
 * This test distinguishes between a product that does not exist (404 Not Found) and a product with no reviews (200 with zero values). The endpoint must reject non-existent products with a clear error rather than silently returning empty statistics.
 *
 * 1. Customer registers and authenticates via authorize_customer_join.
 * 2. A random UUID is generated that does not correspond to any product.
 * 3. The review statistics endpoint is called with the invalid productId.
 * 4. The call is expected to throw an HttpError with status 404.
 */
export async function test_api_review_statistics_product_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Call review statistics with a non-existent product ID
  await TestValidator.httpError(
    "non-existent product returns 404",
    404,
    async () => {
      await api.functional.shoppingMall.customer.products.review_statistics.at(
        customerConnection,
        {
          productId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );
}

