/**
 * Test review statistics retrieval for a seller's product that has received one 5-star review.
 *
 * Validates the complete lifecycle leading to review statistics computation: administrator and seller setup, product creation with variant and stock, customer purchase through the full order workflow (paid → shipped → delivered), review submission, and finally the review statistics endpoint.
 *
 * The core validation confirms that when a product has exactly one non-deleted 5-star review, the computed averageRating equals 5.0 and totalCount equals 1. This verifies the endpoint correctly sums rating values, divides by the count of non-deleted reviews, and rounds to one decimal place per the IShoppingMallReviewStatistic specification.
 *
 * 1. Administrator registers and creates a product category.
 * 2. Seller registers and is approved by the administrator.
 * 3. Approved seller creates a product under the category.
 * 4. Customer registers on the platform.
 * 5. Seller creates a variant with stock for the product.
 * 6. Customer adds the variant to cart and places an order.
 * 7. Seller creates a shipment for the order items.
 * 8. Customer confirms shipment delivery.
 * 9. Customer writes a 5-star review for the delivered product.
 * 10. Seller retrieves review statistics and verifies averageRating and totalCount.
 */
export async function test_api_review_statistics_product_with_reviews(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {});
