            referrer: true,
            created_at: true,
            expired_at: true,
          },
        }),
        MyGlobal.prisma.shopping_mall_guest_sessions.count({ where }),
      ]);
      counts.push(count);
      for (const row of rows) {
        allResults.push({
          actorType: "guest",
          id: row.id,
          actorId: row.shopping_mall_guest_id,
