      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      ...ShoppingMallSellerPasswordResetAtSummaryTransformer.select(),
    });
  const total =
    await MyGlobal.prisma.shopping_mall_seller_password_resets.count({
