export async function getShoppingMallSellerProductsProductIdVariantsVariantCodeSnapshotsSnapshotId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  variantCode: string;
  snapshotId: string & tags.Format<"uuid">;
