export async function getShoppingMallSellerOrderItemsItemId(props: {
  seller: SellerPayload;
  itemId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallOrderItem> {
  const authCheck = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: props.itemId },
    select: {
      productVariant: {
        select: {
          product: {
            select: {
              shopping_mall_seller_id: true,
            },
          },
        },
      },
    },
  });
  if (
    !authCheck ||
    authCheck.productVariant.product.shopping_mall_seller_id !== props.seller.id
  ) {
    throw new HttpException("Not Found", 404);
  }
  const record =
    await MyGlobal.prisma.shopping_mall_order_items.findUniqueOrThrow({
      where: { id: props.itemId },
      ...ShoppingMallOrderItemTransformer.select(),
    });
  return await ShoppingMallOrderItemTransformer.transform(record);
}

