import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IShoppingMallSeller } from "../../../../api/structures/IShoppingMallSeller";
import { postShoppingMallAuthSellerJoin } from "../../../../providers/postShoppingMallAuthSellerJoin";
import { postShoppingMallAuthSellerLogin } from "../../../../providers/postShoppingMallAuthSellerLogin";
import { postShoppingMallAuthSellerRefresh } from "../../../../providers/postShoppingMallAuthSellerRefresh";

@Controller("/shoppingMall/auth/seller")
export class ShoppingmallAuthSellerController {
  /**
   * Register a new seller account on the platform.
   *
   * Creates a seller account with the provided email and password. The new seller starts in "pending" approval status and must be approved by an administrator before gaining access to product management, order processing, and the seller dashboard.
   *
   * Upon successful registration, the seller is automatically authenticated — an access token and refresh token pair are issued. The session is recorded in shopping_mall_seller_sessions with the client's IP address, the page URL (href), and the HTTP referrer for security auditing.
   *
   * The access token is short-lived and used to authenticate subsequent API requests. The refresh token is longer-lived and can be used to obtain new access tokens without re-entering credentials.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller registration credentials containing email and password.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Register a new seller account with email and password.
   *
   * Implementation:
   * 1. Validate email format and uniqueness (shopping_mall_sellers has @@unique on email)
   * 2. Validate password meets minimum strength requirements (minimum 8 characters)
   * 3. Hash password using bcrypt, store in password_hash column
   * 4. Insert into shopping_mall_sellers with approval_status = 'pending'
   * 5. Create session in shopping_mall_seller_sessions: seller_id, ip, href, referrer, created_at (now), expired_at (refresh token lifetime)
   * 6. Generate JWT access token and refresh token bound to the session id
   * 7. Return both tokens with expiration timestamps
   *
   * Edge cases:
   * - Email already registered: 409 Conflict
   * - Invalid email format: 400 Bad Request
   * - Password too short/weak: 400 Bad Request
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.IJoin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate a seller using email and password credentials.
   *
   * Validates the seller's email and password against the stored credentials in shopping_mall_sellers. Upon successful authentication, a new session record is created in shopping_mall_seller_sessions capturing the login's IP address, page URL, and referrer. A short-lived access token and a longer-lived refresh token are issued.
   *
   * Banned sellers (banned_at is set) are prevented from logging in entirely. Suspended sellers (suspended_at is set) can still log in — suspension only hides products from listings and blocks new product creation while preserving access to existing order processing.
   *
   * Sellers in any approval status (pending, approved, rejected) can log in. Pending sellers have limited functionality until an administrator approves their account. Rejected sellers can view their rejection reason and submit a new registration request.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Seller login credentials containing email and password.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Authenticate a seller with email and password credentials.
   *
   * Implementation:
   * 1. Find seller by email in shopping_mall_sellers (case-insensitive)
   * 2. Verify deleted_at IS NULL (account must be active)
   * 3. Verify banned_at IS NULL (banned sellers cannot log in)
   * 4. Compare password against stored password_hash using bcrypt
   * 5. Create session in shopping_mall_seller_sessions: seller_id, ip, href, referrer, created_at (now), expired_at (refresh token lifetime)
   * 6. Generate JWT access token and refresh token
   * 7. Return both tokens with expiration timestamps
   *
   * Edge cases:
   * - Email not found: 401 Unauthorized (do not reveal whether email exists)
   * - Wrong password: 401 Unauthorized
   * - Account soft-deleted (deleted_at not null): 401 Unauthorized
   * - Account banned (banned_at not null): 403 Forbidden with ban notification
   * - Account suspended (suspended_at not null): login still allowed; suspension only limits selling features at the application layer
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IShoppingMallSeller.ILogin,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Obtain a new access token using a valid refresh token.
   *
   * Allows sellers to maintain their authenticated session without re-entering credentials. The refresh token is validated against the active session record in shopping_mall_seller_sessions. If the session is valid and not expired, a new access token is issued.
   *
   * Refresh token rotation may be applied — a new refresh token can be issued alongside the new access token, extending the session lifetime recorded in the session's expired_at timestamp. Expired or revoked refresh tokens are rejected.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for obtaining new access credentials.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Refresh an expiring or expired access token using a valid refresh token.
   *
   * Implementation:
   * 1. Validate the refresh token's cryptographic signature and expiration claim
   * 2. Look up the corresponding session in shopping_mall_seller_sessions by the session ID encoded in the refresh token
   * 3. Verify session exists and expired_at > current timestamp
   * 4. Verify the associated seller account is still active: deleted_at IS NULL, banned_at IS NULL
   * 5. Generate a new JWT access token bound to the same session
   * 6. Optionally rotate the refresh token: issue new refresh token, update session expired_at
   * 7. Return new token pair with expiration timestamps
   *
