import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IPageIShoppingMallAdmin } from "../../../../api/structures/IPageIShoppingMallAdmin";
import { IShoppingMallAdmin } from "../../../../api/structures/IShoppingMallAdmin";
import { AdminAuth } from "../../../../decorators/AdminAuth";
import { AdminPayload } from "../../../../decorators/payload/AdminPayload";
import { getShoppingMallAdminAdminsAdminId } from "../../../../providers/getShoppingMallAdminAdminsAdminId";
import { patchShoppingMallAdminAdmins } from "../../../../providers/patchShoppingMallAdminAdmins";
import { postShoppingMallAdminAdminsAdminIdDemote } from "../../../../providers/postShoppingMallAdminAdminsAdminIdDemote";
import { postShoppingMallAdminAdminsAdminIdPromote } from "../../../../providers/postShoppingMallAdminAdminsAdminIdPromote";

@Controller("/shoppingMall/admin/admins")
export class ShoppingmallAdminAdminsController {
  /**
   * Lists all platform administrator accounts with pagination and filtering support.
   *
   * This endpoint provides administrators with visibility into who holds administrative access on the platform. Both regular administrators and super administrators can browse the list. The response includes each administrator's unique identifier, email address, authority grade, and account timestamps. Password hashes are never exposed in the response.
   *
   * Super administrators rely on this list to identify candidates for promotion to super administrator or demotion to regular administrator. Regular administrators use it for general awareness of the administrative team composition. Soft-deleted (deactivated) administrator accounts are excluded by default — use the includeDeleted filter to include them when auditing historical access.
   *
   * @param connection
   * @param body Search and filter criteria including email text search, authority grade filter, creation date range bounds, pagination parameters, and an option to include soft-deleted (deactivated) administrator accounts.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Query the shopping_mall_admins table with cursor-based pagination and filtering.
   *
   * Apply the following optional filters from the request body:
   * - email: partial case-insensitive text match (ILIKE or LOWER LIKE)
   * - grade: exact match on "regular" or "super"
   * - createdAt.from / createdAt.to: inclusive date range bounds on created_at
   * - includeDeleted: boolean; when true, include records where deleted_at IS NOT NULL; when false or omitted, apply WHERE deleted_at IS NULL
   *
   * Default sort by created_at descending (newest first). Never include password_hash in any response field set.
   *
   * Authorization: accept requests from authenticated administrators of both grades (regular and super). Reject requests from unauthenticated users, guests, customers, and sellers with a 403 Forbidden response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IShoppingMallAdmin.IRequest,
  ): Promise<IPageIShoppingMallAdmin.ISummary> {
    try {
      return await patchShoppingMallAdminAdmins({
        admin,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves detailed information about a specific platform administrator identified by their unique ID.
   *
   * This endpoint returns the administrator's email address, authority grade (regular or super), and account timestamps including creation and last modification dates. The password hash is never included in the response for security.
   *
   * Soft-deleted administrator accounts — those that have been deactivated — are treated as if they do not exist, resulting in a 404 response. Only active administrator accounts can be retrieved.
   *
   * This operation is available to both regular administrators and super administrators as part of their platform oversight responsibilities.
   *
   * @param connection
   * @param adminId Unique identifier of the administrator to retrieve. This is a UUID value assigned at account creation.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Query the shopping_mall_admins table by the provided adminId UUID. Return 404 if no record exists or if the deleted_at field is non-null — soft-deleted accounts are treated as not found. Exclude the password_hash column from the SELECT query; never return hashed credentials in API responses. Return the following columns: id, email, grade, created_at, updated_at. No joins are required; this is a single-table read. No pagination or filtering is needed as this returns exactly one record.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":adminId")
  public async at(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("adminId")
    adminId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await getShoppingMallAdminAdminsAdminId({
        admin,
        adminId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Promotes a regular administrator to the super administrator grade.
   *
   * This operation is exclusively available to super administrators and grants the target administrator the full authority associated with the super administrator grade — including the ability to approve and reject administrator requests, manage seller approvals, promote and demote other administrators, and perform all other administrative oversight functions.
   *
   * The promotion takes effect immediately without requiring the target administrator's consent. The operation is recorded in the administrator audit log for accountability.
   *
   * A regular administrator cannot promote themselves or other administrators. Only existing super administrators may perform this action. An administrator who is already at the super administrator grade cannot be promoted again.
   *
   * @param connection
   * @param adminId The unique identifier of the administrator to promote to super administrator grade.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Promote a regular administrator to super administrator grade.
   *
   * Authorization: The authenticated actor MUST be a super administrator (grade = "super"). If the actor is a regular administrator or any other role, reject with 403 Forbidden.
   *
   * Target resolution: Look up the admin by adminId in the shopping_mall_admins table. If the admin record does not exist or has a non-null deleted_at (soft-deleted), reject with 404 Not Found.
   *
   * Grade validation: Verify the target admin's current grade is "regular". If the target admin is already a super administrator (grade = "super"), reject with 409 Conflict — promotion is only applicable to regular administrators.
   *
   * Self-promotion: If the acting super administrator attempts to promote themselves (actor ID equals adminId), this is allowed if they are currently a regular administrator (caught by the grade check above). A super administrator promoting themselves would fail the grade check since they are already "super".
   *
   * Update: Set the target admin's grade to "super" and update updated_at to the current timestamp.
   *
   * Audit log: Insert a record into shopping_mall_admin_audit_logs with: shopping_mall_admin_id = acting super admin's ID, action_type = "promote_admin", target_entity_type = "admin", target_entity_id = target admin's ID, old_value = "regular", new_value = "super", created_at = current timestamp. The reason field may be null — promotion does not require justification per platform policy.
   *
   * Response: Return the updated admin record (IShoppingMallAdmin) reflecting the new grade.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post(":adminId/promote")
  public async promote(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("adminId")
    adminId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await postShoppingMallAdminAdminsAdminIdPromote({
        admin,
        adminId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Demotes a super administrator to the regular administrator grade.
   *
   * This endpoint is exclusively accessible to super administrators. It downgrades another super administrator to regular administrator status, immediately revoking their elevated privileges — including the ability to manage administrator applications and promote or demote other administrators — while preserving their regular administrative capabilities (category management, seller approval, order oversight, user management) and all associated account data.
   *
   * Self-demotion is strictly prohibited. A super administrator cannot target their own account; attempting to do so will result in an error. An administrator who is already at the regular grade cannot be demoted further.
   *
   * @param connection
   * @param adminId Unique identifier of the super administrator to demote (UUID).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification Update the target administrator's grade from "super" to "regular".
   *
   * Authorization: Only super administrators may call this endpoint. Regular administrators and other actors must be rejected with a 403 Forbidden error.
   *
   * Self-demotion prevention: Compare the authenticated administrator's ID against the {adminId} path parameter. If they match, reject with a 400 Bad Request error indicating that self-demotion is not permitted.
   *
   * Grade validation: Query the shopping_mall_admins table by {adminId}. If the target administrator does not exist or has a non-null deleted_at, return 404 Not Found. If the target administrator's grade is already "regular", return 400 Bad Request indicating the administrator is already at the regular grade and cannot be demoted further.
   *
   * On success: Update the target administrator's grade column to "regular" and set updated_at to the current timestamp. Return the complete administrator record (excluding password_hash) as the response body.
   *
   * Audit: This is a sensitive administrative action. The downstream implementation should log this event in shopping_mall_admin_audit_logs.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post(":adminId/demote")
  public async demote(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("adminId")
    adminId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallAdmin> {
    try {
      return await postShoppingMallAdminAdminsAdminIdDemote({
        admin,
        adminId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

