    try {
      return await postShoppingMallSellerProductsProductIdVariantsVariantIdOptions(
        {
          seller,
          productId,
          variantId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Updates the key or value of an existing option value for a product variant.
   *
   * Option values define the distinguishing attributes that differentiate one variant from another — such as color, size, or material. Each variant may have multiple option values, but each key (dimension name) must be unique within the variant. This operation allows the seller to rename an option dimension or change its value.
