    try {
      return await patchShoppingMallSellerProductsProductIdSnapshots({
        seller,
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves a single product snapshot by its unique identifier, showing the complete state of the product at the moment that snapshot was captured.
   *
   * Product snapshots are automatically created every time a seller edits any field of their product, preserving a historical record of the product's name, description, category, base price, images, and all variant details as they existed just before the edit. Snapshots are immutable — they can never be modified or deleted by any actor under any circumstance, including after the original product is deleted.
   *
   * This endpoint returns the full snapshot detail including all product images with their display order and all variant snapshots with their SKU codes, option values, prices, and stock quantities at the time of capture. The recorded category name is included if the category still exists in the system.
