import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IPageIShoppingMallOrderItem } from "../../../../../api/structures/IPageIShoppingMallOrderItem";
import { IShoppingMallOrderItem } from "../../../../../api/structures/IShoppingMallOrderItem";
import { CustomerAuth } from "../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../decorators/payload/CustomerPayload";
import { getShoppingMallCustomerOrdersOrderCodeItemsItemId } from "../../../../../providers/getShoppingMallCustomerOrdersOrderCodeItemsItemId";
import { patchShoppingMallCustomerOrdersOrderIdItems } from "../../../../../providers/patchShoppingMallCustomerOrdersOrderIdItems";

@Controller("/shoppingMall/customer/orders")
export class ShoppingmallCustomerOrdersItemsController {
  /**
   * Retrieves the list of order items within a specific order, with optional status filtering and pagination.
   *
   * Each order item represents a specific product variant purchased in the order, recording the quantity, unit price frozen at purchase time, and an independent lifecycle status. Order items are the finest unit for post-purchase operations — every action including shipment assignment, cancellation, refund, and delivery confirmation operates at the individual order item level.
   *
   * Status filtering allows callers to narrow results to items in a specific state. Valid filter values are "paid" (awaiting shipment), "shipped" (in transit), "delivered" (confirmed received), "cancelled" (pre-shipment cancellation approved), and "refunded" (post-delivery refund approved).
   *
   * Access to this endpoint is scoped by actor role. Customers see only items from their own orders. Sellers see only items for their products, enabling order fulfillment workflows. Administrators have unrestricted access to all order items for oversight and force-action capabilities.
   *
   * @param connection
   * @param orderId Unique identifier of the order whose items are being listed. References the shopping_mall_orders table primary key.
   * @param body Optional filtering criteria including item status filter and pagination parameters. When status filter is omitted, all items in the order are returned.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the shopping_mall_order_items table where shopping_mall_order_id matches the given {orderId} path parameter.
   *
   * Apply status filtering when the request body includes a status value. Valid status values are: "paid", "shipped", "delivered", "cancelled", "refunded". Filter by exact match on the status column when provided.
   *
   * Support pagination via cursor-based or offset-based parameters from the request body. Default sort order: by created_at ascending (chronological order of item creation matching order placement sequence).
   *
   * Return each order item with its core fields: id, shopping_mall_product_variant_id, shopping_mall_shipment_id (null if not yet shipped), quantity, price, status, created_at, updated_at.
   *
   * Access control:
   * - Customer: only items belonging to their own orders. Verify that shopping_mall_orders.shopping_mall_customer_id matches the authenticated customer.
   * - Seller: only items whose shopping_mall_product_variant_id references a variant belonging to a product owned by the authenticated seller. Join through shopping_mall_product_variants → shopping_mall_products → shopping_mall_seller_profiles.
   * - Administrator: all items in the order without restriction.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch(":orderId/items")
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("orderId")
    orderId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallOrderItem.IRequest,
  ): Promise<IPageIShoppingMallOrderItem.ISummary> {
    try {
      return await patchShoppingMallCustomerOrdersOrderIdItems({
        customer,
        orderId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieves the full details of a single order item within a specific order.
   *
   * This endpoint returns comprehensive information about an individual line item, including the purchased variant details, quantity, the unit price frozen at the moment of order creation, and the current lifecycle status. The order item is the fundamental unit for all post-purchase operations — fulfillment tracking, cancellation requests, and refund requests each operate at this level independently.
   *
   * Access is scoped by actor role. Customers may only view items belonging to their own orders. Sellers may only view items originating from their own products. Administrators have unrestricted access to any order item across the platform. A 403 response is returned if the requesting actor lacks permission.
   *
   * The response includes purchase-time snapshots of the product, variant, and seller profile, preserving the exact context at the moment of purchase. This historical integrity is maintained even if the underlying products, variants, or seller profiles have since been modified, suspended, or deleted. If the item has been assigned to a shipment, the associated carrier name and tracking number are included. Any active cancellation or refund requests linked to this item are also returned.
   *
   * If the order item does not exist or belongs to a different order than the one identified by the order code, the endpoint returns a 404 response.
   *
   * @param connection
   * @param orderCode The human-readable order number identifying the parent order (global scope). This unique code is assigned at order creation and displayed to customers in their order history, to sellers in their order dashboards, and to administrators in order management views.
   * @param itemId The unique identifier of the order item to retrieve. This UUID is assigned at order creation when each purchased variant becomes an individual order item with its own independent status lifecycle.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Retrieve a single order item by its UUID within the context of a specific order identified by its unique order code.
   *
   * Query the shopping_mall_order_items table where id = itemId. Join with shopping_mall_orders to verify the order item belongs to the order identified by orderCode: match shopping_mall_order_id with the order whose code equals orderCode. If the order code does not correspond to the item's parent order, return 404 — the item does not reside within the specified order.
   *
   * Authorization checks:
   * - Customer: verify the order's shopping_mall_customer_id matches the authenticated customer's ID. If not, return 403.
   * - Seller: trace from the order item through shopping_mall_product_variant_id to shopping_mall_product_variants, then through the product variant to shopping_mall_products, verifying the product's seller matches the authenticated seller's ID. If not, return 403.
   * - Admin: no ownership restriction — access any order item on the platform.
   *
   * Include related data for comprehensive detail:
   * - The parent order summary: code, status, created_at
   * - The product variant reference: SKU code, option values (from shopping_mall_product_variant_option_values joined through shopping_mall_product_variants)
   * - Purchase-time snapshot data from shopping_mall_order_item_product_snapshots, shopping_mall_order_item_variant_snapshots, and shopping_mall_order_item_seller_snapshots — include snapshot data inline if available
   * - Associated shipment information if shopping_mall_shipment_id is set: carrier name, tracking number, and shipping date from shopping_mall_shipments
   * - Active cancellation requests (shopping_mall_cancellation_requests where shopping_mall_order_item_id matches) and refund requests (shopping_mall_refund_requests where shopping_mall_order_item_id matches) linked to this item
   *
   * Edge cases:
   * - If the order item's id does not exist at all, return 404
