import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IShoppingMallOrderItemProductSnapshot } from "../../../../../api/structures/IShoppingMallOrderItemProductSnapshot";
import { CustomerAuth } from "../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../decorators/payload/CustomerPayload";
import { getShoppingMallCustomerOrderItemsItemIdProductSnapshot } from "../../../../../providers/getShoppingMallCustomerOrderItemsItemIdProductSnapshot";

@Controller("/shoppingMall/customer/order-items/:itemId/product-snapshot")
export class ShoppingmallCustomerOrder_itemsProduct_snapshotController {
  /**
   * Retrieves the product snapshot captured at the time of order placement for a specific order item.
   *
   * This snapshot preserves the exact state of the purchased product — including its name, description, category, base price, and all gallery images with their display order — as they appeared when the customer placed the order. The data is permanently frozen and never changes, providing an authoritative historical record even if the seller later modifies or deletes the original product.
   *
   * The response includes all product snapshot images captured at purchase time, preserving the gallery arrangement the customer saw. If the original product or category has been deleted since the order was placed, the snapshot data remains intact and the denormalized fields (name, description, base_price, category_name) continue to serve accurate historical information.
   *
   * Access is scoped to the authenticated user's role: customers can view snapshots for their own order items, sellers can view snapshots for order items containing their products, and administrators can view any product snapshot.
   *
   * @param connection
   * @param itemId Unique identifier of the order item whose product snapshot to retrieve. This is the UUID primary key of the shopping_mall_order_items record.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the shopping_mall_order_item_product_snapshots table using the itemId path parameter, matching against shopping_mall_order_item_id (unique constraint ensures at most one record).
   *
   * Include the related shopping_mall_order_item_product_snapshot_images via the productSnapshotImages HAS relation, ordered by display_order ascending to preserve the gallery arrangement as it appeared at purchase time.
   *
   * Authorization:
   * - Customer: verify the order item belongs to an order owned by the authenticated customer (join through shopping_mall_order_items → shopping_mall_orders → shopping_mall_customer_id).
   * - Seller: verify the order item's product variant belongs to a product owned by the authenticated seller (join through shopping_mall_order_items → shopping_mall_product_variants → shopping_mall_products → shopping_mall_seller_profile_id → shopping_mall_seller_profiles → shopping_mall_user_id).
   * - Admin: no ownership restriction — can access any product snapshot.
   *
   * Edge cases:
   * - If the order item does not exist, return 404.
   * - If the product snapshot does not exist for the order item (should not happen under normal operation since snapshots are created at order time), return 404.
   * - The snapshot is immutable — this is a read-only endpoint with no write operations.
   * - The referenced shopping_mall_product_id and shopping_mall_category_id may be null if the original records were deleted; rely on the denormalized name, description, base_price, and category_name fields for display.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallOrderItemProductSnapshot> {
    try {
      return await getShoppingMallCustomerOrderItemsItemIdProductSnapshot({
        customer,
        itemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

