import { getShoppingMallCustomerOrderItemsItemIdVariantSnapshot } from "../../../../../providers/getShoppingMallCustomerOrderItemsItemIdVariantSnapshot";

@Controller("/shoppingMall/customer/order-items/:itemId/variant-snapshot")
export class ShoppingmallCustomerOrder_itemsVariant_snapshotController {
  /**
   * Retrieves the variant snapshot associated with a specific order item.
   *
   * Each order item captures a variant snapshot at the moment of order placement, preserving the exact SKU code, option values, and unit price as they existed at purchase time. This snapshot is immutable — it reflects what the customer actually purchased regardless of later changes to the original product variant by the seller.
   *
   * **Data Included**
   *
   * The response includes the variant SKU code (the unique product identifier within the seller's catalog), the option values as a human-readable description (e.g., "Color: Red, Size: Large"), and the frozen unit price. A timestamp records when the snapshot was created, which coincides with order placement.
   *
   * **Immutability**
   *
   * Variant snapshots are permanently immutable. No actor — including customers, sellers, administrators, or super administrators — can modify or delete a snapshot. This guarantees that order history remains accurate and auditable for financial reconciliation and dispute resolution.
   *
   * **Accessibility**
   *
   * This snapshot is accessible to the customer who owns the order, the seller whose product was purchased, and platform administrators for oversight purposes.
   *
   * @param connection
   * @param itemId UUID of the order item whose variant snapshot is being retrieved. (global scope — each order item has exactly one variant snapshot)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the shopping_mall_order_item_variant_snapshots table filtering by shopping_mall_order_item_id equal to the path parameter itemId.
   *
   * This is a 1:1 relationship — each order item has exactly one variant snapshot created at order placement time. Retrieve all fields: id, shopping_mall_order_item_id, sku_code, option_values, price, and created_at.
   *
   * Error handling:
   * - Return 404 if no order item exists with the given itemId
   * - Return 404 if the order item exists but no variant snapshot is associated (should not occur under normal conditions, as snapshots are created atomically with order placement per section 288)
   *
   * This is a read-only operation. Never perform any write, update, or delete on the snapshot record — snapshots are immutable per section 448. Authorization: the requesting actor must be the customer who owns the order, the seller whose variant was purchased, or an administrator.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallOrderItemVariantSnapshot> {
    try {
      return await getShoppingMallCustomerOrderItemsItemIdVariantSnapshot({
        customer,
        itemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

